/* Tamil Bodha text for the phase 1 Ganita lessons. [[id|words]] marks a tappable key word (gloss.<id>). Draft translation: needs review by a native-speaker teacher. */
window.Sutra.i18n.add('ta', {
  'bodha.M2.what': 'பெருக்கல் ஒரு [[rect|செவ்வகத்தை]] மூடும் கட்டங்களை எண்ணும்.',
  'bodha.M2.can': 'தரையில் எத்தனை ஓடுகள் உள்ளன என்று ஒவ்வொன்றாக எண்ணாமல் கண்டுபிடிக்க முடியும்.',
  'bodha.M2.idea': 'குறுக்கே 6 ஓடு, கீழே 4 ஓடு என்றால் 4 வரிசைகள். ஒவ்வொரு வரிசையிலும் 6 ஓடுகள். ஆக மொத்தம் 6 × 4 ஓடுகள்.',
  'bodha.M2.why': 'ஒவ்வொரு வரிசையும் ஒரே அளவு, அதனால் ஓடுகளை எண்ணாமல் வரிசைகளை எண்ணலாம்: 6, 12, 18, 24. சம வரிசைகளை இப்படி எண்ணுவதே [[mult|பெருக்கல்]].',
  'bodha.M2.example': 'குறுக்கே 5, கீழே 3 என்ற தரையை எத்தனை ஓடுகள் மூடும்?',
  'bodha.M2.example1': 'ஒரு வரிசையில் 5 ஓடுகள்.',
  'bodha.M2.example2': '3 வரிசைகள், ஐந்துகளாக எண்ணு: 5, 10, 15.',
  'bodha.M2.example3': '5 × 3 = 15 ஓடுகள்.',
  'bodha.M2.where': 'தரை ஓடுகள், திரையரங்கு இருக்கைகள், முட்டைத் தட்டு, அஞ்சல் தாள் — எல்லாம் ஒரே அளவு வரிசைகள்.',
  'bodha.M2.sutra': 'பெருக்கல் செவ்வகத்தை மூடும் கட்டங்களை எண்ணும்: வரிசைகள் × நெடுக்க வரிசைகள்.',

  'bodha.M4.what': '23 × 14 போன்ற பெரிய எண்களைப் பெருக்க, செவ்வகத்தை எளிய துண்டுகளாக வெட்டுவோம்.',
  'bodha.M4.can': 'இரண்டு இலக்க எண்களைப் பெருக்கவும், நெடுவரிசைக் கணக்கு ஏன் வேலை செய்கிறது என்றும் புரியும்.',
  'bodha.M4.idea': '23-ஐ 20, 3 ஆகவும், 14-ஐ 10, 4 ஆகவும் பிரி. செவ்வகம் நான்கு [[room|அறைகளாக]] மாறும். ஒவ்வொரு அறையும் எளிய பெருக்கல்.',
  'bodha.M4.why': 'வெட்டினாலும் கட்டங்கள் கூடவோ குறையவோ செய்யாது. நான்கு அறைகள் சேர்ந்தால் முழுச் செவ்வகம்: 200 + 30 + 80 + 12 = 322.',
  'bodha.M4.example': '17 × 12-ஐ அறைகளால் கணக்கிடு.',
  'bodha.M4.example1': '17-ஐ 10, 7 ஆகவும், 12-ஐ 10, 2 ஆகவும் பிரி.',
  'bodha.M4.example2': 'அறைகள்: 10 × 10 = 100, 7 × 10 = 70, 10 × 2 = 20, 7 × 2 = 14.',
  'bodha.M4.example3': 'அறைகளைக் கூட்டு: 100 + 70 + 20 + 14 = 204.',
  'bodha.M4.where': 'கடைக்காரர்கள் மனதில் இப்படிச் செய்வார்கள்: ₹23-க்கு 12 பேனாக்கள் என்றால் 12 × 20 + 12 × 3. புத்தகத்தின் நெடுவரிசைக் கணக்கும் அதே அறைகள், வரிகளாக.',
  'bodha.M4.sutra': 'பெரிய எண்களைப் பத்துகள், ஒன்றுகளாக வெட்டு, ஒவ்வொரு அறையையும் பெருக்கு, பிறகு அறைகளைக் கூட்டு.',

  'bodha.M5.what': 'இரண்டு விஷயங்கள் வேறு வேறு வேகத்தில் மீண்டும் மீண்டும் வந்தால், சில சமயம் ஒன்றாக வரும். எப்போது என்று கண்டுபிடிக்கலாம்.',
  'bodha.M5.can': 'இரண்டு தாளங்கள் முதலில் எப்போது சந்திக்கின்றன — [[lcm|பொது மடங்கின்]] மீச்சிறு மதிப்பு — கண்டுபிடிக்க முடியும்.',
  'bodha.M5.idea': '3 தாளத்துக்கு ஒருமுறை அடிக்கும் மேளம் 3, 6, 9, 12-ல் அடிக்கும். இவை 3-ன் [[multiple|பிரகுகள்]]. 4 தாளத்துக்கு ஒருமுறை அடிப்பவர் 4, 8, 12-ல் அடிக்கும்.',
  'bodha.M5.why': 'இரண்டு பட்டியல்களிலும் உள்ள தாளத்தில் சேர்ந்து அடிப்பார்கள். முதல் தாளம் இரண்டு பெருக்கல் பட்டியல்களிலும் உள்ள மீச்சிறு எண்: 12.',
  'bodha.M5.example': 'ஒருவர் 4 தாளத்துக்கும், மற்றவர் 6 தாளத்துக்கும் அடிக்கிறார். முதலில் எப்போது சேர்ந்து அடிப்பார்கள்?',
  'bodha.M5.example1': '4-ன் பிரகுகள்: 4, 8, 12, 16, 20, 24.',
  'bodha.M5.example2': '6-ன் பிரகுகள்: 6, 12, 18, 24.',
  'bodha.M5.example3': 'இரண்டு பட்டியல்களிலும் முதல் எண் 12; 4 × 6 = 24 அல்ல.',
  'bodha.M5.where': '15, 20 நிமிடத்துக்கு ஒருமுறை வரும் பேருந்துகள், வேறு தாளங்களில் மேளம், வேறு நாட்களில் மீண்டும் மீண்டும் வரும் வேலைகள்.',
  'bodha.M5.sutra': 'இரண்டு தாளங்கள் முதலில் சந்திக்கும் இடம் இரண்டு பெருக்கல் பட்டியல்களிலும் உள்ள மீச்சிறு எண்.',

  'bodha.D1.what': 'சமமாகப் பகிர்வது ஒவ்வொரு குழுவுக்கும் ஒரே அளவு கிடைக்கும். அதுதான் [[divide|வகுத்தல்]].',
  'bodha.D1.can': 'மொத்தத்தைச் சமமாகப் பகிரவும், பெருக்கலால் பதிலைச் சரிபார்க்கவும் முடியும்.',
  'bodha.D1.idea': '12 லட்டுகளை 4 தட்டுகளில் பகிர, ஒவ்வொரு தட்டுக்கும் ஒன்று வைத்து மீண்டும் மீண்டும், காலியாகும் வரை. ஒவ்வொரு தட்டுக்கும் 3.',
  'bodha.D1.why': 'வகுத்தல் பெருக்கலைத் திருப்புகிறது. 4 தட்டுகளில் ஒவ்வொன்றுக்கும் 3 என்றால் 4 × 3 = 12, தொடங்கிய மொத்தம்.',
  'bodha.D1.example': '15 மாம்பழங்களை 5 நண்பர்களிடம் பகிர்.',
  'bodha.D1.example1': 'ஒவ்வொருவருக்கும் ஒரு மாம்பழம்: 5 பயன்படுத்தப்பட்டது.',
  'bodha.D1.example2': 'மீண்டும் சுற்று: 3 சுற்றுகளுக்குப் பிறகு 15 முடிந்தது.',
  'bodha.D1.example3': 'ஒவ்வொருவருக்கும் 3. சரிபார்: 5 × 3 = 15.',
  'bodha.D1.where': 'பிறந்தநாளில் இனிப்பு பகிர்தல், பில் பிரித்தல், அணியில் சம எண்ணிக்கை குழந்தைகள்.',
  'bodha.D1.sutra': 'சமமாகப் பகிர்வது ஒவ்வொரு குழுவுக்கும் ஒரே அளவு; சரிபார்க்க பெருக்கு.',

  'bodha.D3.what': 'சில சமயம் மொத்தம் சமமாகப் பிரியாது. மீதி இருப்பவை [[remainder|மீதி]].',
  'bodha.D3.can': 'மீதியுடன் பகிரவும், மீதியைப் பின்னங்களாக வெட்டவும் முடியும்.',
  'bodha.D3.idea': '14 லட்டுகளை 4 தட்டுகளில் பகிர: ஒவ்வொன்றுக்கும் 3, 2 மீதி. 14 ÷ 4 = 3 மீதி 2.',
  'bodha.D3.why': '2 மீதி லட்டுகளை வெட்டலாம். ஒவ்வொன்றையும் 2 சம பாகங்களாக: 4 பாதிகள், ஒவ்வொரு தட்டுக்கும் இன்னும் ஒன்று. ஒவ்வொன்றுக்கும் 3½.',
  'bodha.D3.example': '7 ரொட்டிகளை 2 குழந்தைகளிடம் பகிர்.',
  'bodha.D3.example1': 'ஒவ்வொரு குழந்தைக்கும் 3 ரொட்டி, 1 மீதி.',
  'bodha.D3.example2': 'கடைசி ரொட்டியை 2 சம பாகங்களாக வெட்டு.',
  'bodha.D3.example3': 'ஒவ்வொருவருக்கும் 3½ ரொட்டி: 3½.',
  'bodha.D3.where': 'மீதி ரொட்டிகள், நண்பர்களிடம் சாக்லேட் பகிர்தல், சம துண்டுகளாக நாடா வெட்டுதல்.',
  'bodha.D3.sutra': 'மீதியை வீசுவதில்லை: சம துண்டுகளாக வெட்டினால் பின்னங்கள் ஆகின்றன.',

  'bodha.G2.what': '[[perimeter|சுற்றளவு]] என்பது வடிவத்தைச் சுற்றியுள்ள நீளம். [[area|பரப்பளவு]] என்பது உள்ளே உள்ள இடம்.',
  'bodha.G2.can': 'அதே சுற்றளவில் வேறு வேறு பரப்பளவு இருக்க முடியும் என்று பார்க்க முடியும்.',
  'bodha.G2.idea': '24 மீ கயிற்றை செவ்வகமாக முளையில். 11 × 1 மெல்லிய செவ்வகமும் 6 × 6 சதுரமும் அதே கயிறு.',
  'bodha.G2.why': 'கயிறு சுற்றியுள்ள தூரத்தை மட்டும் நிர்ணுக்கிறது செய்கிறது. உள்ளே மெல்லியது 11 ச.மீ, சதுரம் 36 ச.மீ.',
  'bodha.G2.example': '20 மீ கயிற்றில் 8 × 2, 5 × 5 — எது அதிக நிலம்?',
  'bodha.G2.example1': 'இரண்டும் 20 மீ: 8 + 2 + 8 + 2 = 20, 5 + 5 + 5 + 5 = 20.',
  'bodha.G2.example2': '8 × 2 செவ்வகம் 8 × 2 = 16 சதுர மீட்டர் இடத்தைக் கொள்ளும்.',
  'bodha.G2.example3': '5 × 5 சதுரம் 25 சதுர மீட்டர் இடத்தைக் கொள்ளும்: சதுரமே அதிகம்.',
  'bodha.G2.where': 'கம்பி வேலியாகத் தோட்டம், புகைப்பட சட்டகம், விளையாட்டு மைதான எல்லை.',
  'bodha.G2.sutra': 'அதே கயிறு வெவ்வேறு அளவு நிலத்தை அடைக்கலாம்; சதுரம் அதிகம் அடைக்கிறது.',

  'bodha.G4.what': 'சமச்சீர் என்றால் ஒரு அமைப்பு நகர்த்தினாலும் பொருந்தும். இரண்டு வகை: [[mirror|கண்ணாடி]] மற்றும் [[turn|திருப்பம்]].',
  'bodha.G4.can': 'கோலத்தில் கண்ணாடிச் சமச்சீரையும் திருப்பச் சமச்சீரையும் பிரித்து அறிய முடியும்.',
  'bodha.G4.idea': 'கண்ணாடிக் கோடு அமைப்பை மடிக்கும்போது இரண்டு பக்கங்களும் பொருந்தும், புத்தகம் மூடுவது போல. திருப்பம் மையத்தைச் சுற்றி சுழன்றால் மீண்டும் பொருந்தும்.',
  'bodha.G4.why': 'இரண்டும் வேறு நகர்வு; ஒன்று இருந்து மற்றது இல்லாமல் இருக்கலாம். சிறகு சக்கரம் கால் திருப்பத்தில் பொருந்தும், கண்ணாடிக் கோடு இல்லை.',
  'bodha.G4.example': 'சிறகு சக்கர அமைப்பைப் பார்.',
  'bodha.G4.example1': 'எந்தக் கோட்டிலும் மடிக்கினால் பக்கங்கள் பொருந்தாது. கண்ணாடிக் கோடு இல்லை.',
  'bodha.G4.example2': 'கால் திருப்பம் (90°): அதேபோல் இருக்கும்.',
  'bodha.G4.example3': 'திருப்பச் சமச்சீர் உண்டு, கண்ணாடிச் சமச்சீர் இல்லை.',
  'bodha.G4.where': 'வாசல் கோலம், ஜாலி ஜன்னல், பூ, விசிறி சங்கிலி.',
  'bodha.G4.sutra': 'கண்ணாடிக் கோடு அமைப்பை மடிக்கிறது; திருப்பம் அதைச் சுழற்றிப் பொருத்துகிறது. இரண்டும் வேறு.',

  'bodha.S2.what': '[[set|கணம்]] என்பது ஒரு விதியைப் பின்பற்றும் பொருள்களின் குழு. சில பொருள்கள் இரண்டு கணங்களிலும் இருக்கும்.',
  'bodha.S2.can': 'இரண்டு வளையங்களால் வகைப்படுத்தவும், மற்றும், அல்லது, இல்லை சொற்களைப் பயன்படுத்தவும் முடியும்.',
  'bodha.S2.idea': 'வளையம் A மஞ்சள் கட்டைகள். வளையம் B வட்டங்கள். மஞ்சள் வட்டம் இரண்டிலும் — வளையங்கள் சேர்ந்து நடுவில்.',
  'bodha.S2.why': 'நடுவில் “மஞ்சள் மற்றும் வட்டம்”. வளையங்களுக்குள் எங்கேனும் “மஞ்சள் அல்லது வட்டம்”. வெளியே “மஞ்சள் இல்லை, வட்டம் இல்லை”.',
  'bodha.S2.example': 'ஒவ்வொரு கட்டையும் எங்கே போகும்?',
  'bodha.S2.example1': 'பச்சை வட்டம்: வட்டம் ஆனால் மஞ்சள் இல்லை — B மட்டும்.',
  'bodha.S2.example2': 'மஞ்சள் சதுரம்: மஞ்சள் ஆனால் வட்டம் இல்லை — A மட்டும்.',
  'bodha.S2.example3': 'கருப்பு முக்கோணம்: இரண்டிலும் இல்லை — வெளியே.',
  'bodha.S2.where': 'கிரிக்கெட் பிடிக்கும் குழந்தைகள், கால்பந்து பிடிக்கும் குழந்தைகள், இரண்டும் பிடிக்கும் குழந்தைகள். இனிப்பு, வாடுத்த உணவு, இரண்டும் உணவு.',
  'bodha.S2.sutra': 'இரண்டு வளையங்கள் சேரும் இடத்தில் பொருள் ஒரே நேரத்தில் இரண்டு கணங்களிலும்.',

  'bodha.L2.what': 'AND, OR, NOT தர்க்கச் சொற்களை ஆம்/இல்லை பதில் தரும் இயந்திரங்களாகக் கட்டலாம்.',
  'bodha.L2.can': 'AND, OR, NOT இயந்திரங்கள் எந்தக் கதவுகளிலும் என்ன செய்யும் என்று முன்னே சொல்ல முடியும்.',
  'bodha.L2.idea': 'AND இயந்திரம் A, B இரண்டும் திறந்தால் மட்டுமே ஆம். OR இயந்திரம் குறைந்தது ஒன்று திறந்தால் ஆம்.',
  'bodha.L2.why': 'NOT பதிலைத் திருப்பும்: திறந்தால் இல்லை, மூடியால் ஆம். ஒவ்வொரு [[truth|உண்மை அட்டவணையால்]] எல்லா முயற்சியும் சரிபார்க்கலாம்.',
  'bodha.L2.example': 'கதவு A திறந்தது, B மூடியது.',
  'bodha.L2.example1': 'AND-க்கு இரண்டும் திறக்க வேண்டும்: பதில் இல்லை.',
  'bodha.L2.example2': 'OR-க்கு குறைந்தது ஒன்று திறந்தால் போதும்: பதில் ஆம்.',
  'bodha.L2.example3': 'A-வில் NOT “திற”-ஐ இல்லை ஆக்கும்.',
  'bodha.L2.where': 'கதவு மூடியும் பொத்தான் அழுத்தியும் தான் லிப்ட் நகரும். “மழை இல்லை என்றால் வெளியே போ.”',
  'bodha.L2.sutra': 'AND-க்கு இரண்டும், OR-க்குக் குறைந்தது ஒன்று, NOT பதிலைத் திருப்பும்.',

  'gloss.rect': 'நான்கு நேர் பக்கங்கள், நான்கு செங்கோண மூலைகள் கொண்ட தட்டை வடிவம்.',
  'gloss.mult': 'சம குழுக்களை விரைவாகக் கூட்டுதல்: 6 × 4 என்றால் 6-ஐ 4 முறை.',
  'gloss.room': 'வெட்டப்பட்ட செவ்வகத்தின் ஒரு துண்டு: சிறிய, எளிய பெருக்கல்.',
  'gloss.lcm': 'இரண்டு பெருக்கல் பட்டியல்களிலும் உள்ள மீச்சிறு எண்.',
  'gloss.multiple': 'பெருக்கல் பட்டியலில் உள்ள எண்: 3, 6, 9, 12 ஆகியவை 3-ன் பிரகுகள்.',
  'gloss.divide': 'மொத்தத்தைச் சம குழுக்களாகப் பகிர்தல்.',
  'gloss.remainder': 'சமமாகப் பிரியாதபோது மீதி.',
  'gloss.perimeter': 'வடிவத்தைச் சுற்றியுள்ள தூரம்.',
  'gloss.area': 'வடிவம் மூடும் தட்டை இடம், சதுரங்களில் எண்ணப்படும்.',
  'gloss.mirror': 'அமைப்பின் இரு பக்கங்களும் பொருந்தும்படி மடிக்கும் கோடு.',
  'gloss.turn': 'மையத்தைச் சுற்றி அமைப்பைச் சுழற்றி மீண்டும் பொருத்துதல்.',
  'gloss.set': 'அனைத்தும் ஒரே விதியைப் பின்பற்றும் பொருள்களின் குழு.',
  'gloss.truth': 'ஒவ்வொரு உள்ளீட்டுக்கும் பதிலுடன் எல்லா முயற்சிகளின் அட்டவணை.'
});
